macro_rules! get {
    ($buf:ident, $idx:expr_2021) => {
        unsafe { *$buf.get_kinda_unchecked($idx as usize) }
    };
}
macro_rules! err {
    ($idx:ident, $num:expr_2021) => {
        return Err(Error::new_c($idx, $num as char, ErrorType::InvalidNumber))
    };
}

macro_rules! check_overflow {
    ($overflowed:ident, $buf:ident, $idx:ident, $start_idx:ident, $end_index:ident) => {
        if $overflowed {
            #[cfg(not(feature = "big-int-as-float"))]
            {
                err!($idx, get!($buf, $idx))
            }
            #[cfg(feature = "big-int-as-float")]
            {
                return f64_from_parts_slow(
                    unsafe { $buf.get_kinda_unchecked($start_idx..$end_index) },
                    $start_idx,
                );
            }
        }
    };
}

#[cfg_attr(not(feature = "no-inline"), inline)]
#[allow(clippy::cast_possible_truncation)]
fn multiply_as_u128(a: u64, b: u64) -> (u64, u64) {
    let res: u128 = u128::from(a) * u128::from(b);
    (res as u64, (res >> 64) as u64)
}

impl Deserializer<'_> {
    #[allow(
        unused_unsafe,
        clippy::cast_possible_wrap,
        clippy::cast_possible_truncation,
        clippy::too_many_lines
    )]
    pub(crate) fn parse_number(idx: usize, buf: &[u8], negative: bool) -> Result<StaticNode> {
        let start_idx = idx;
        let mut idx = idx;
        if negative {
            idx += 1;
            if !is_integer(get!(buf, idx)) {
                err!(idx, get!(buf, idx))
            }
        }
        let mut start = idx;
        let mut num: u64 = 0;
        if get!(buf, idx) == b'0' {
            idx += 1;
            if is_not_structural_or_whitespace_or_exponent_or_decimal(get!(buf, idx)) {
                err!(idx, get!(buf, idx))
            }
        } else {
            if !is_integer(get!(buf, idx)) {
                err!(idx, get!(buf, idx))
            }
            num = u64::from(get!(buf, idx) - b'0');
            idx += 1;
            while is_integer(get!(buf, idx)) {
                num = 10_u64
                    .wrapping_mul(num)
                    .wrapping_add(u64::from(get!(buf, idx) - b'0'));
                idx += 1;
            }
        }
        let mut exponent: i64 = 0;
        let mut is_float = false;
        if get!(buf, idx) == b'.' {
            is_float = true;
            idx += 1;
            let first_after_period = idx as i64;
            if is_integer(get!(buf, idx)) {
                num = 10_u64
                    .wrapping_mul(num)
                    .wrapping_add(u64::from(get!(buf, idx) - b'0'));
                idx += 1;
            } else {
                err!(idx, get!(buf, idx))
            }

            #[cfg(feature = "swar-number-parsing")]
            {
                // safety: we have 8 bytes
                let chars: [u8; 8] =
                    unsafe { *(buf.get_kinda_unchecked(idx..idx + 8).as_ptr().cast()) };
                if is_made_of_eight_digits_fast(chars) {
                    num = 100_000_000_u64.wrapping_mul(num).wrapping_add(u64::from(
                        parse_eight_digits_unrolled(unsafe { buf.get_kinda_unchecked(idx..) }),
                    ));
                    idx += 8;
                }
            }
            while is_integer(get!(buf, idx)) {
                num = 10_u64
                    .wrapping_mul(num)
                    .wrapping_add(u64::from(get!(buf, idx) - b'0'));
                idx += 1;
            }
            exponent = first_after_period.wrapping_sub(idx as i64);
        }
        let mut digit_count = idx - start_idx - 1;
        match get!(buf, idx) {
            b'e' | b'E' => {
                is_float = true;
                idx += 1;
                let neg_exp: bool;
                match get!(buf, idx) {
                    b'-' => {
                        neg_exp = true;
                        idx += 1;
                    }
                    b'+' => {
                        neg_exp = false;
                        idx += 1;
                    }
                    _ => {
                        neg_exp = false;
                    }
                }
                if !is_integer(get!(buf, idx)) {
                    err!(idx, get!(buf, idx))
                }
                let mut exp_number = i64::from(get!(buf, idx) - b'0');
                idx += 1;
                if is_integer(get!(buf, idx)) {
                    exp_number = 10 * exp_number + i64::from(get!(buf, idx) - b'0');
                    idx += 1;
                }
                if is_integer(get!(buf, idx)) {
                    exp_number = 10 * exp_number + i64::from(get!(buf, idx) - b'0');
                    idx += 1;
                }
                while is_integer(get!(buf, idx)) {
                    if exp_number > 0x0001_0000_0000 {
                        err!(idx, get!(buf, idx))
                    }
                    exp_number = 10 * exp_number + i64::from(get!(buf, idx) - b'0');
                    idx += 1;
                }
                exponent += if neg_exp { -exp_number } else { exp_number };
            }
            _ => {}
        }
        if is_float {
            if unlikely!(digit_count >= 19) {
                let start_digits = get!(buf, start) as usize;
                while get!(buf, start) == b'0' || get!(buf, start) == b'.' {
                    start += 1;
                }
                digit_count = digit_count.wrapping_sub(start.wrapping_sub(start_digits));
                if digit_count >= 19 {
                    return f64_from_parts_slow(
                        unsafe { buf.get_kinda_unchecked(start_idx..idx) },
                        start_idx,
                    );
                }
            }
            if is_structural_or_whitespace(get!(buf, idx)) == 0 {
                err!(idx, get!(buf, idx))
            }
            f64_from_parts(
                !negative,
                num,
                exponent as i32,
                unsafe { buf.get_kinda_unchecked(start_idx..idx) },
                start_idx,
            )
        } else if unlikely!(digit_count >= 18) {
            digitcount += 1;
            d = unsafe { *buf.get_kinda_unchecked(digitcount) };
            // the is_made_of_eight_digits_fast routine is unlikely to help here because
            // we rarely see large integer parts like 123456789
            while is_integer(d) {
                digit = d - b'0';
                if let Some(i1) = i
                    .checked_mul(10)
                    .and_then(|i| i.checked_add(u128::from(digit)))
                {
                    i = i1;
                } else {
                    return Err(Self::error_c(
                        idx + digitcount,
                        d as char,
                        ErrorType::Overflow,
                    ));
                }
                digitcount += 1;
                d = unsafe { *buf.get_kinda_unchecked(digitcount) };
            }
        }

        if negative && i > 170_141_183_460_469_231_731_687_303_715_884_105_728_u128 {
            //i64::MIN * -1
            return Err(Self::error_c(
                idx + digitcount,
                d as char,
                ErrorType::Overflow,
            ));
        }

        if is_structural_or_whitespace(d) == 0 {
            Err(Self::error_c(
                idx + digitcount,
                d as char,
                ErrorType::InvalidNumber,
            ))
        } else if negative {
            let i = unsafe { static_cast_i128!(i.wrapping_neg()) };
            if let Ok(i) = i64::try_from(i) {
                Ok(StaticNode::I64(i))
            } else {
                Ok(StaticNode::I128(i))
            }
        } else if let Ok(i) = u64::try_from(i) {
            Ok(StaticNode::U64(i))
        } else {
            Ok(StaticNode::U128(i))
        }
    }

    // parse the number at buf + offset
    // define JSON_TEST_NUMBERS for unit testing
    #[cfg_attr(not(feature = "no-inline"), inline)]
    #[allow(
        clippy::cast_possible_truncation,
        clippy::cast_sign_loss,
        clippy::cast_precision_loss,
        clippy::cast_possible_wrap,
        clippy::too_many_lines
    )]
    pub(crate) fn parse_number(idx: usize, buf: &[u8], negative: bool) -> Result<StaticNode> {
        let buf = unsafe { buf.get_kinda_unchecked(idx..) };
        let mut byte_count = usize::from(negative);
        let mut ignore_count: u8 = 0;
        //let startdigits: *const u8 = p;
        let mut i: u64;
        let mut d = unsafe { *buf.get_kinda_unchecked(byte_count) };
        let mut digit: u8;
        if d == b'0' {
            // 0 cannot be followed by an integer
            byte_count += 1;
            d = unsafe { *buf.get_kinda_unchecked(byte_count) };
            if is_not_structural_or_whitespace_or_exponent_or_decimal(d) {
                return Err(Self::error_c(
                    idx + byte_count,
                    d as char,
                    ErrorType::InvalidNumber,
                ));
            }
        unsafe {
            Self::_find_structural_bits::<impls::simd128::SimdInput>(input, structural_indexes)
        }
    }
}

impl<'de> Deserializer<'de> {
    /// Extracts the tape from the Deserializer
    #[must_use]
    pub fn into_tape(self) -> Tape<'de> {
        Tape(self.tape)
    }

    /// Gives a `Value` view of the tape in the Deserializer
    #[must_use]
    pub fn as_value(&self) -> Value<'_, 'de> {
        // Skip initial zero
        Value(&self.tape)
    }

    /// Resets the Deserializer tape index to 0
    pub fn restart(&mut self) {
        // Skip initial zero
        self.idx = 0;
    }

    #[cfg_attr(not(feature = "no-inline"), inline)]
    fn error(error: ErrorType) -> Error {
        Error::new(0, None, error)
    }

    #[cfg_attr(not(feature = "no-inline"), inline)]
    fn error_c(idx: usize, c: char, error: ErrorType) -> Error {
        Error::new(idx, Some(c), error)
    }

    /// Creates a serializer from a mutable slice of bytes
    ///
    /// # Errors
    ///
    /// Will return `Err` if `s` is invalid JSON.
    pub fn from_slice(input: &'de mut [u8]) -> Result<Self> {
        let len = input.len();

        let mut buffer = Buffers::new(len);

        Self::from_slice_with_buffers(input, &mut buffer)
    }

    /// Fills the tape without creating a serializer, this function poses
    /// lifetime chalanges and can be frustrating, howver when it is
    /// usable it allows a allocation free (armotized) parsing of JSON
    ///
    /// # Errors
    ///
    /// Will return `Err` if `input` is invalid JSON.
    #[allow(clippy::uninit_vec)]
    #[cfg_attr(not(feature = "no-inline"), inline)]
    fn fill_tape(
        input: &'de mut [u8],
        buffer: &mut Buffers,
        tape: &mut Vec<Node<'de>>,
    ) -> Result<()> {
        const LOTS_OF_ZOERS: [u8; SIMDINPUT_LENGTH] = [0; SIMDINPUT_LENGTH];
        let len = input.len();
        let simd_safe_len = len + SIMDINPUT_LENGTH;

        if len > u32::MAX as usize {
            return Err(Self::error(ErrorType::InputTooLarge));
        }

        buffer.string_buffer.clear();
        buffer.string_buffer.reserve(len + SIMDJSON_PADDING);

